import { DatabaseSync } from 'node:sqlite';
import { mkdirSync } from 'node:fs';
import { dirname } from 'node:path';

export function validateText(text) {
  if (typeof text !== 'string' || !text.trim() || text.trim().length > 4000)
    throw new Error('Text must be a string containing 1–4000 characters');
  return text.trim();
}
export function normalizeTag(tag) {
  if (typeof tag !== 'string' || !tag.trim() || tag.trim().length > 40)
    throw new Error('Tags must be nonempty strings of at most 40 characters');
  return tag.trim().toLowerCase();
}
export function validateTags(tags) {
  if (!Array.isArray(tags)) throw new Error('Tags must be an array');
  return [...new Set(tags.map(normalizeTag))].sort();
}
export function validateId(id) {
  if (!Number.isSafeInteger(id) || id < 1) throw new Error('ID must be a positive integer');
  return id;
}
export function openStore(path) {
  mkdirSync(dirname(path), {recursive:true});
  const db = new DatabaseSync(path);
  db.exec(`PRAGMA foreign_keys=ON; PRAGMA busy_timeout=5000;
    CREATE TABLE IF NOT EXISTS notes(id INTEGER PRIMARY KEY,text TEXT NOT NULL,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
    CREATE TABLE IF NOT EXISTS tags(name TEXT PRIMARY KEY);
    CREATE TABLE IF NOT EXISTS note_tags(note_id INTEGER REFERENCES notes(id) ON DELETE CASCADE,tag TEXT REFERENCES tags(name),PRIMARY KEY(note_id,tag));`);
  const transaction = fn => {
    db.exec('SAVEPOINT notes_write');
    try { const result = fn(); db.exec('RELEASE notes_write'); return result; }
    catch (error) { db.exec('ROLLBACK TO notes_write; RELEASE notes_write'); throw error; }
  };
  const getNote = id => {
    validateId(id);
    const row = db.prepare('SELECT * FROM notes WHERE id=?').get(id);
    if (!row) return null;
    return {id:Number(row.id), text:row.text, createdAt:row.created_at, updatedAt:row.updated_at,
      tags:db.prepare('SELECT tag FROM note_tags WHERE note_id=? ORDER BY tag').all(id).map(r=>r.tag)};
  };
  const attachTags = (id, tags) => {
    for (const tag of tags) {
      db.prepare('INSERT OR IGNORE INTO tags VALUES(?)').run(tag);
      db.prepare('INSERT INTO note_tags VALUES(?,?)').run(id,tag);
    }
  };
  return {
    transaction,
    createNote(text, tags=[]) {
      text = validateText(text); tags = validateTags(tags);
      return transaction(() => {
        const now = new Date().toISOString();
        const id = Number(db.prepare('INSERT INTO notes(text,created_at,updated_at) VALUES(?,?,?)').run(text,now,now).lastInsertRowid);
        attachTags(id,tags);
        return getNote(id);
      });
    },
    getNote,
    listNotes({q,tag,limit=50,offset=0}={}) {
      if (!Number.isInteger(limit) || limit < 1 || limit > 100) throw new Error('Limit must be an integer from 1 to 100');
      if (!Number.isSafeInteger(offset) || offset < 0) throw new Error('Offset must be a nonnegative integer');
      if (q !== undefined && typeof q !== 'string') throw new Error('Query must be a string');
      const clauses = [], values = [];
      if (q !== undefined) { clauses.push('instr(lower(text), lower(?)) > 0'); values.push(q); }
      if (tag !== undefined) { clauses.push('EXISTS (SELECT 1 FROM note_tags WHERE note_id=notes.id AND tag=?)'); values.push(normalizeTag(tag)); }
      return db.prepare(`SELECT id FROM notes ${clauses.length ? 'WHERE '+clauses.join(' AND ') : ''} ORDER BY id DESC LIMIT ? OFFSET ?`)
        .all(...values,limit,offset).map(row=>getNote(Number(row.id)));
    },
    updateNote(id, patch) {
      validateId(id);
      if (!patch || typeof patch !== 'object' || Array.isArray(patch)) throw new Error('Patch must be an object');
      const hasText = Object.hasOwn(patch,'text'), hasTags = Object.hasOwn(patch,'tags');
      const text = hasText ? validateText(patch.text) : undefined;
      const tags = hasTags ? validateTags(patch.tags) : undefined;
      return transaction(() => {
        const old = getNote(id);
        if (!old) return null;
        const now = new Date(Math.max(Date.now(), Date.parse(old.updatedAt)+1)).toISOString();
        db.prepare('UPDATE notes SET text=?,updated_at=? WHERE id=?').run(hasText ? text : old.text,now,id);
        if (hasTags) { db.prepare('DELETE FROM note_tags WHERE note_id=?').run(id); attachTags(id,tags); }
        return getNote(id);
      });
    },
    deleteNote(id) { validateId(id); return db.prepare('DELETE FROM notes WHERE id=?').run(id).changes > 0; },
    listTags() { return db.prepare('SELECT tag AS name, COUNT(*) AS count FROM note_tags GROUP BY tag ORDER BY tag').all().map(r=>({name:r.name,count:Number(r.count)})); },
    close() { db.close(); }
  };
}

import {validateText, validateTags} from './store.mjs';

// Validate every field before the first write, including tags in later records.
export function importNotes(store, records) {
  if (!Array.isArray(records)) throw new Error('notes must be an array');
  const prepared = records.map(record => {
    if (!record || typeof record !== 'object' || Array.isArray(record)) throw new Error('Each note must be an object');
    return {text:validateText(record.text), tags:validateTags(record.tags === undefined ? [] : record.tags)};
  });
  const write = () => prepared.map(record => store.createNote(record.text,record.tags));
  return typeof store.transaction === 'function' ? store.transaction(write) : write();
}

export function allNotes(store) {
  const notes = [];
  for (let offset=0;;offset+=100) {
    const batch = store.listNotes({limit:100,offset});
    notes.push(...batch);
    if (batch.length < 100) return notes;
  }
}
export function exportNotes(store) {
  return {version:1, notes:allNotes(store).reverse().map(({text,tags})=>({text,tags}))};
}

import {createInterface} from 'node:readline';
import {openStore} from './store.mjs';
import {importNotes, exportNotes, allNotes} from './import.mjs';

const args = process.argv.slice(2);
const dbIndex = args.indexOf('--db');
const store = openStore(dbIndex < 0 ? 'data/notes.sqlite' : args[dbIndex+1]);
const string = {type:'string'}, id = {type:'integer',minimum:1};
const tags = {type:'array',items:{type:'string',minLength:1,maxLength:40}};
const note = {type:'object',properties:{text:{type:'string',minLength:1,maxLength:4000},tags},required:['text'],additionalProperties:false};
const schema = (properties={},required=[]) => ({type:'object',properties,required,additionalProperties:false});
const tools = [
  {name:'notes_create',description:'Create a note',inputSchema:note},
  {name:'notes_get',description:'Get a note by ID',inputSchema:schema({id},['id'])},
  {name:'notes_list',description:'Search and list notes, newest first',inputSchema:schema({q:string,tag:string,limit:{type:'integer',minimum:1,maximum:100},offset:{type:'integer',minimum:0}})},
  {name:'notes_update',description:'Replace note text or tags',inputSchema:schema({id,text:note.properties.text,tags},['id'])},
  {name:'notes_delete',description:'Delete a note',inputSchema:schema({id},['id'])},
  {name:'tags_list',description:'List tags and counts',inputSchema:schema()},
  {name:'notes_export',description:'Export all notes in oldest-first order',inputSchema:schema()},
  {name:'notes_import',description:'Atomically import a batch of notes',inputSchema:schema({notes:{type:'array',items:note}},['notes'])}
];
function callTool(name, input) {
  const tool = tools.find(tool=>tool.name===name);
  if (!tool) throw new Error('Unknown tool');
  if (!input || typeof input !== 'object' || Array.isArray(input)) throw new Error('Arguments must be an object');
  for (const key of tool.inputSchema.required) if (!Object.hasOwn(input,key)) throw new Error(`Missing ${key}`);
  for (const key of Object.keys(input)) if (!Object.hasOwn(tool.inputSchema.properties,key)) throw new Error(`Unknown argument ${key}`);
  switch (name) {
    case 'notes_create': return store.createNote(input.text,input.tags);
    case 'notes_get': return store.getNote(input.id);
    case 'notes_list': return store.listNotes(input);
    case 'notes_update': { const {id,...patch}=input; return store.updateNote(id,patch); }
    case 'notes_delete': return store.deleteNote(input.id);
    case 'tags_list': return store.listTags();
    case 'notes_export': return exportNotes(store);
    case 'notes_import': return importNotes(store,input.notes);
  }
}
const rpcError = (code,message) => Object.assign(new Error(message),{code});
function dispatch(message) {
  const params = message.params ?? {};
  switch (message.method) {
    case 'initialize': return {protocolVersion:'2024-11-05',capabilities:{tools:{},resources:{}},serverInfo:{name:'quick-notes',version:'1.0.0'}};
    case 'notifications/initialized': case 'ping': return {};
    case 'tools/list': return {tools};
    case 'tools/call': {
      try { return {content:[{type:'text',text:JSON.stringify(callTool(params.name,params.arguments ?? {}))}]}; }
      catch(error) { return {isError:true,content:[{type:'text',text:error.message}]}; }
    }
    case 'resources/list': return {resources:[{uri:'notes://all',name:'All notes',mimeType:'application/json'}]};
    case 'resources/read':
      if (params.uri !== 'notes://all') throw rpcError(-32002,'Unknown resource');
      return {contents:[{uri:'notes://all',mimeType:'application/json',text:JSON.stringify(allNotes(store))}]};
    default: throw rpcError(-32601,'Method not found');
  }
}
const send = value => process.stdout.write(JSON.stringify(value)+'\n');
const lines = createInterface({input:process.stdin,crlfDelay:Infinity});
lines.on('line',line=>{
  if (!line.trim()) return;
  let message;
  try { message = JSON.parse(line); }
  catch { send({jsonrpc:'2.0',id:null,error:{code:-32700,message:'Parse error'}}); return; }
  if (!message || Array.isArray(message) || message.jsonrpc !== '2.0' || typeof message.method !== 'string' ||
      (Object.hasOwn(message,'id') && message.id !== null && typeof message.id !== 'string' && typeof message.id !== 'number')) {
    send({jsonrpc:'2.0',id:null,error:{code:-32600,message:'Invalid request'}}); return;
  }
  const hasId = Object.hasOwn(message,'id');
  try { const result=dispatch(message); if (hasId) send({jsonrpc:'2.0',id:message.id,result}); }
  catch(error) { if (hasId) send({jsonrpc:'2.0',id:message.id,error:{code:error.code ?? -32602,message:error.message}}); }
});
lines.on('close',()=>store.close());

import {createServer} from 'node:http';
import {openStore} from './store.mjs';
import {importNotes, exportNotes} from './import.mjs';

const args = process.argv.slice(2);
const option = (name,fallback) => args.includes(name) ? args[args.indexOf(name)+1] : fallback;
const store = openStore(option('--db','data/notes.sqlite'));
const escape = value => String(value).replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
const httpError = (status,message) => Object.assign(new Error(message),{status});
const json = (res,value,status=200) => { res.writeHead(status,{'Content-Type':'application/json; charset=utf-8'}); res.end(JSON.stringify(value)); };
const html = (res,body,status=200) => {
  res.writeHead(status,{'Content-Type':'text/html; charset=utf-8'});
  res.end(`<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Quick Notes</title><style>
  body{font:16px system-ui;max-width:850px;margin:2rem auto;padding:0 1rem;background:#f5f7fa;color:#182230}article,section{background:white;padding:1rem;margin:1rem 0;border:1px solid #d9dfe8;border-radius:8px}textarea{width:100%;box-sizing:border-box;min-height:100px}input,button,textarea{font:inherit;padding:.5rem;margin:.25rem 0}button{cursor:pointer}a{color:#245eb1}.text{white-space:pre-wrap;overflow-wrap:anywhere}.tag{display:inline-block;background:#e9eef9;padding:.2rem .5rem;margin:.2rem;border-radius:4px}.error{color:#a01919}label{display:block}nav{display:flex;gap:1rem}small{color:#556}
  </style></head><body><h1><a href="/">Quick Notes</a></h1>${body}</body></html>`);
};
const form = (note={text:'',tags:[]}) => `<form method="post" action="${note.id ? '/notes/'+note.id : '/notes'}"><label>Text<textarea name="text" maxlength="4000" required>${escape(note.text)}</textarea></label><label>Tags (comma separated)<input name="tags" value="${escape(note.tags.join(', '))}"></label><button>${note.id ? 'Save changes' : 'Create note'}</button></form>`;
const tagLink = name => `<a class="tag" href="/?tag=${escape(encodeURIComponent(name))}">${escape(name)}</a>`;
function collectionOptions(params) {
  const result={};
  for (const key of ['q','tag']) if (params.has(key)) result[key]=params.get(key);
  for (const key of ['limit','offset']) if (params.has(key)) {
    if (!/^\d+$/.test(params.get(key))) throw new Error(`${key} must be an integer`);
    result[key]=Number(params.get(key));
  }
  return result;
}
function dashboard(res,params) {
  const pageText=params.get('page') ?? '1';
  if (!/^\d+$/.test(pageText) || !Number.isSafeInteger(Number(pageText)) || Number(pageText)<1) throw new Error('Page must be a positive integer');
  const page=Number(pageText), filters={};
  for (const key of ['q','tag']) if (params.has(key)) filters[key]=params.get(key);
  const notes=store.listNotes({...filters,limit:20,offset:(page-1)*20});
  const more=store.listNotes({...filters,limit:1,offset:page*20}).length>0;
  const pageLink = n => { const p=new URLSearchParams(filters); p.set('page',String(n)); return '/?'+escape(p.toString()); };
  html(res,`<section><h2>New note</h2>${form()}</section>
    <section><h2>Search</h2><form method="get" action="/"><label>Search text <input name="q" value="${escape(filters.q ?? '')}"></label><label>Tag <input name="tag" value="${escape(filters.tag ?? '')}"></label><button>Filter</button> <a href="/">Clear</a></form>
    <div>${store.listTags().map(({name,count})=>`${tagLink(name)} (${count})`).join(' ')}</div></section>
    <h2>Notes</h2>${notes.length ? notes.map(note=>`<article><div class="text">${escape(note.text)}</div><div>${note.tags.map(tagLink).join(' ')}</div><small>#${note.id} · ${escape(note.updatedAt)}</small><p><a href="/notes/${note.id}/edit">Edit</a></p><form method="post" action="/notes/${note.id}/delete"><button>Delete</button></form></article>`).join('') : '<p>No notes found.</p>'}
    <nav>${page>1 ? `<a href="${pageLink(page-1)}">Previous</a>` : ''}<span>Page ${page}</span>${more ? `<a href="${pageLink(page+1)}">Next</a>` : ''}</nav>`);
}
async function body(req,asJson) {
  let text='';
  for await (const chunk of req) {
    text+=chunk.toString();
    if (Buffer.byteLength(text)>2*1024*1024) throw new Error('Request body too large');
  }
  if (asJson) {
    let value;
    try { value=JSON.parse(text); } catch { throw new Error('Invalid JSON body'); }
    if (!value || typeof value!=='object' || Array.isArray(value)) throw new Error('Body must be an object');
    return value;
  }
  const fields=new URLSearchParams(text);
  return {text:fields.get('text'),tags:(fields.get('tags') ?? '').split(',').map(tag=>tag.trim()).filter(Boolean)};
}
const redirect = res => {res.writeHead(303,{Location:'/'});res.end();};
const requireNote = id => { const note=store.getNote(id); if (!note) throw httpError(404,'Note not found'); return note; };
const server=createServer(async(req,res)=>{
  const url=new URL(req.url,'http://localhost');
  const path=url.pathname, api=path.startsWith('/api/');
  try {
    if (req.method==='GET' && path==='/') return dashboard(res,url.searchParams);
    if (path==='/api/notes') {
      if (req.method==='GET') return json(res,store.listNotes(collectionOptions(url.searchParams)));
      if (req.method==='POST') {const value=await body(req,true);return json(res,store.createNote(value.text,value.tags),201);}
    }
    if (req.method==='GET' && path==='/api/tags') return json(res,store.listTags());
    if (req.method==='GET' && path==='/api/export') return json(res,exportNotes(store));
    if (req.method==='POST' && path==='/api/import') return json(res,importNotes(store,(await body(req,true)).notes),201);
    const apiNote=path.match(/^\/api\/notes\/(\d+)$/);
    if (apiNote) {
      const id=Number(apiNote[1]); requireNote(id);
      if (req.method==='GET') return json(res,store.getNote(id));
      if (req.method==='PATCH') return json(res,store.updateNote(id,await body(req,true)));
      if (req.method==='DELETE') return json(res,store.deleteNote(id));
    }
    if (req.method==='POST' && path==='/notes') {
      const value=await body(req,false); store.createNote(value.text,value.tags); return redirect(res);
    }
    const formNote=path.match(/^\/notes\/(\d+)(\/edit|\/delete)?$/);
    if (formNote) {
      const id=Number(formNote[1]), note=requireNote(id);
      if (req.method==='GET' && formNote[2]==='/edit') return html(res,`<h2>Edit note</h2>${form(note)}<a href="/">Cancel</a>`);
      if (req.method==='POST' && formNote[2]==='/delete') {store.deleteNote(id);return redirect(res);}
      if (req.method==='POST' && !formNote[2]) {store.updateNote(id,await body(req,false));return redirect(res);}
    }
    throw httpError(404,'Not found');
  } catch(error) {
    const status=error.status ?? 400;
    if (api) json(res,{error:error.message},status);
    else html(res,`<h2 class="error">${escape(error.message)}</h2><p><a href="/">Back to notes</a></p>`,status);
  }
});
server.listen(Number(option('--port','8080')),'127.0.0.1',()=>console.log(JSON.stringify({port:server.address().port})));
for (const signal of ['SIGINT','SIGTERM']) process.on(signal,()=>server.close(()=>{store.close();process.exit(0);}));

